import{_ as n,C as s,o as e,c as h,j as i,E as t,a as l,a3 as o}from"./chunks/framework.C6R8kWFE.js";const I=JSON.parse(`{"title":"14-dars (Mentor). UI dizayn: tugmalar, menyular, HUD (1-qism): Tugmalar turlari, holatlari (Normal, Hover, Pressed)","description":"","frontmatter":{"title":"14-dars (Mentor). UI dizayn: tugmalar, menyular, HUD (1-qism): Tugmalar turlari, holatlari (Normal, Hover, Pressed)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":5,"link":"/mentor/9-sinf-game/hafta-05/"},"g":14,"title":"UI dizayn: tugmalar, menyular, HUD (1-qism): Tugmalar turlari, holatlari (Normal, Hover, Pressed)","lead":"«START» tugmasini bosganingizda u biroz botib ketadi va o'yin boshlanadi. Shu kichik o'zgarish — dizaynerning puxta ishi. Bugun o'yin tugmalarini o'zimiz yaratamiz.","slide":"/slaydlar/9-sinf-game/hafta-05/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-05/dars-2-test.html","student_link":"/9-sinf-game/hafta-05/dars-2","tabs":[{"g":13,"link":"/mentor/9-sinf-game/hafta-05/dars-1","current":false},{"g":14,"link":"/mentor/9-sinf-game/hafta-05/dars-2","current":true},{"g":15,"link":"/mentor/9-sinf-game/hafta-05/dars-3","current":false}],"prev":{"g":13,"title":"O'yin uchun ikonka va spraytlar yaratish (3-qism): Sprayt sheet (atlas) tayyorlash va optimallashtirish","link":"/mentor/9-sinf-game/hafta-05/dars-1"},"next":{"g":15,"title":"UI dizayn: tugmalar, menyular, HUD (2-qism): Bosh menyu, sozlamalar va pauza menyusi dizayni","link":"/mentor/9-sinf-game/hafta-05/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-05/dars-2.md","filePath":"mentor/9-sinf-game/hafta-05/dars-2.md"}`),d={name:"mentor/9-sinf-game/hafta-05/dars-2.md"},m={class:"blk"},g={id:"dars-rejasi",tabindex:"-1"},u={class:"blk"},y={id:"mentor-konspekti",tabindex:"-1"},k={class:"blk"},b={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},q={class:"blk"},p={id:"tezkor-nazorat-savollari",tabindex:"-1"},c={class:"blk"},v={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function f(_,a,z,T,x,P){const r=s("Icon");return e(),h("div",null,[i("div",m,[i("h2",g,[t(r,{name:"file-text"}),a[0]||(a[0]=l(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=o("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga UI dizayn tushunchasini va uning o&#39;yindagi rolini, UI-dizaynerning asosiy vazifalarini, asosiy UI elementlarini (tugma, menyu, HUD) tanishtirish; tugmalar turlari (Primary, Secondary, interaktiv) va tugma dizayniga qo&#39;yiladigan talablarni o&#39;rgatish; Photoshop&#39;da tugmaning Normal, Hover va Pressed holatlarini alohida qatlamlarda yaratishni amalda bajarish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar UI dizaynning o&#39;yindagi 5 ta vazifasini ayta oladi; Primary va Secondary tugmani farqlaydi; Photoshop&#39;da Rectangle Tool, Corners, Stroke, Layer Styles (gradient, shadow, glow) bilan «START» tugmasini chizadi va uning 3 ta holatini alohida qatlamlarda tayyorlab, shaffof PNG qilib eksport qiladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>Takrorlash (sprayt sheet, atlas): 10 daqiqa</li><li>Yangi mavzu: UI dizayn, UI-dizayner vazifalari, UI elementlari: 15 daqiqa</li><li>Tugmalar turlari va dizayn talablari: 10 daqiqa</li><li>Amaliyot: Photoshop&#39;da tugma chizish (uslubiy ko&#39;rsatma bo&#39;yicha): 20 daqiqa</li><li>Amaliyot: Normal, Hover, Pressed holatlari va eksport: 20 daqiqa</li><li>Xulosa: 5 daqiqa</li></ul></li></ul><blockquote><p>Manba: o&#39;quv dasturi — «UI dizayn: tugmalar, menyular, HUD» moduli («UI dizayn tushunchasi va o&#39;yinlardagi roli. Foydalanuvchi tajribasiga (UX) ta&#39;siri. O&#39;yinlarda UI-dizaynerning asosiy vazifalari. Tugmalar turlari va dizayni uchun talablar»); o&#39;quv qo&#39;llanma — 2.4-bo&#39;lim (ta&#39;rif, vazifalar, tugmalar turlari, talablar, Photoshop&#39;da UI yaratish bosqichlari: «Tugmalar uchun hover va pressed holatlar alohida layerlarda yaratiladi»); uslubiy ko&#39;rsatma — 1.4-mashg&#39;ulot (1920×1080 hujjat, Rectangle Tool, Corners 30 px, Stroke, Text Tool «START»). Menyular — 15-dars, HUD — keyingi darslar.</p></blockquote><hr>",3))]),i("div",u,[i("h2",y,[t(r,{name:"file-text"}),a[3]||(a[3]=l(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=o(`<h3 id="_1-ui-dizayn-nima" tabindex="-1">1. UI dizayn nima? <a class="header-anchor" href="#_1-ui-dizayn-nima" aria-label="Permalink to &quot;1. UI dizayn nima?&quot;">​</a></h3><p>O&#39;quv qo&#39;llanma ta&#39;rifi: <strong>UI-dizayn</strong> (foydalanuvchi interfeysi dizayni) — tugmalar, menyular, belgilar va o&#39;yinchi o&#39;zaro ta&#39;sir qiladigan boshqa elementlarni o&#39;z ichiga olgan o&#39;yinning vizual va interaktiv qismini yaratish jarayoni. Vazifasi — o&#39;yinni boshqarishni <strong>tushunarli, qulay va estetik jozibali</strong> qilish.</p><p>Interfeys orqali o&#39;yinchi:</p><ul><li>personaj holati (sog&#39;lik, energiya, inventar) haqida ma&#39;lumot oladi;</li><li>o&#39;yin jarayonini boshqaradi (menyu, pauza, qurol tanlash, sozlamalar);</li><li>o&#39;yin dunyosi bilan aloqada bo&#39;ladi (xarita, kvestlar, dialoglar).</li></ul><p>UX bilan bog&#39;liqlik: yaxshi UI o&#39;yinchi tajribasini (UX) yaxshilaydi — «sifatli dizayn o&#39;yin taassurotini yaxshilaydi, yomon dizayn esa o&#39;yinchini chalg&#39;itadi va tushkunlikka olib keladi».</p><h3 id="_2-ui-dizaynerning-asosiy-vazifalari-qo-llanma-bo-yicha" tabindex="-1">2. UI-dizaynerning asosiy vazifalari (qo&#39;llanma bo&#39;yicha) <a class="header-anchor" href="#_2-ui-dizaynerning-asosiy-vazifalari-qo-llanma-bo-yicha" aria-label="Permalink to &quot;2. UI-dizaynerning asosiy vazifalari (qo&#39;llanma bo&#39;yicha)&quot;">​</a></h3><ol><li><strong>Axborotni vizual uzatish</strong> — grafika, animatsiya, tovush orqali tushunarli format.</li><li><strong>Soddalik va aniqlik</strong> — chalg&#39;ituvchi omillarni kamaytirish.</li><li><strong>Muvofiq uyg&#39;unlik</strong> — interfeys o&#39;yin uslubiga mos, muhitni to&#39;ldiradi.</li><li><strong>Funksional imkoniyatlar</strong> — qulay boshqaruv vositalari.</li><li><strong>Estetika va uslub</strong> — ranglar, shriftlar, illyustratsiyalar ko&#39;zga yoqimli va tanib olinadigan.</li></ol><h3 id="_3-asosiy-ui-elementlari" tabindex="-1">3. Asosiy UI elementlari <a class="header-anchor" href="#_3-asosiy-ui-elementlari" aria-label="Permalink to &quot;3. Asosiy UI elementlari&quot;">​</a></h3><ul><li><strong>Tugmalar (Buttons)</strong> — buyruq berish, tanlov, amal bajarish.</li><li><strong>Menyular (Menus)</strong> — imkoniyatlar orasida tanlov tuzilmasi.</li><li><strong>HUD (Head-Up Display)</strong> — o&#39;yin davomida doim ko&#39;rinadigan ma&#39;lumot (nomi aviatsiyadan: uchuvchining old oynasiga tushirilgan ma&#39;lumot).</li><li>Shuningdek: ikonlar, indikatorlar, progress barlar, bildirishnomalar.</li></ul><h3 id="_4-tugmalar-turlari" tabindex="-1">4. Tugmalar turlari <a class="header-anchor" href="#_4-tugmalar-turlari" aria-label="Permalink to &quot;4. Tugmalar turlari&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tur</th><th>Vazifasi</th><th>Misol</th></tr></thead><tbody><tr><td><strong>Asosiy (Primary)</strong></td><td>o&#39;yin boshlash, davom ettirish, tasdiqlash</td><td>Start, OK, Davom etish</td></tr><tr><td><strong>Ikkinchi darajali (Secondary)</strong></td><td>bekor qilish, ortga qaytish</td><td>Cancel, Back, Ortga</td></tr><tr><td><strong>Interaktiv</strong></td><td>hover, bosish (pressed), yoritish yoki animatsiya effektlari bilan</td><td>har qanday «jonli» tugma</td></tr></tbody></table><p>Primary tugma ko&#39;zga birinchi tashlanadi (yorqin rang, kattaroq); Secondary — sokinroq (kulrang, kontur, kichikroq).</p><h3 id="_5-tugma-dizayni-uchun-talablar-qo-llanma" tabindex="-1">5. Tugma dizayni uchun talablar (qo&#39;llanma) <a class="header-anchor" href="#_5-tugma-dizayni-uchun-talablar-qo-llanma" aria-label="Permalink to &quot;5. Tugma dizayni uchun talablar (qo&#39;llanma)&quot;">​</a></h3><ul><li><strong>O&#39;lcham va joylashuv qulay</strong> bo&#39;lishi kerak (telefonda barmoq bilan bosish oson).</li><li><strong>Rang va shakl</strong> boshqa elementlardan ajralib tursin.</li><li><strong>Holatlar (normal, hover, bosilgan) aniq farqlansin.</strong></li><li>Misol: «Start Game» tugmasi odatda <strong>markazda</strong> va e&#39;tiborni tortuvchi rangda (yashil yoki ko&#39;k).</li></ul><h3 id="_6-tugma-holatlari" tabindex="-1">6. Tugma holatlari <a class="header-anchor" href="#_6-tugma-holatlari" aria-label="Permalink to &quot;6. Tugma holatlari&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Holat</th><th>Qachon</th><th>Vizual farq (namuna)</th></tr></thead><tbody><tr><td><strong>Normal</strong></td><td>tugma tinch turibdi</td><td>asosiy rang, yengil soya</td></tr><tr><td><strong>Hover</strong></td><td>kursor ustiga keldi (yoki geympadda tanlangan)</td><td>ochroq rang yoki Outer Glow, biroz kattaroq</td></tr><tr><td><strong>Pressed</strong></td><td>bosilgan payt</td><td>to&#39;qroq rang, soya yo&#39;q yoki ichki soya, 2–4 px pastga siljigan</td></tr></tbody></table><p>Qo&#39;llanmada rangning ham o&#39;rni aytilgan: <em>«UI elementlarda rang orqali interaktivlikni ko&#39;rsatish (masalan, hover holatida tugma rangi o&#39;zgaradi)»</em>. Ba&#39;zi o&#39;yinlarda to&#39;rtinchi holat — <strong>Disabled</strong> (bosib bo&#39;lmaydi, kulrang) ham bo&#39;ladi.</p><h3 id="_7-photoshop-da-tugma-uslubiy-ko-rsatma-1-4-mashg-ulot" tabindex="-1">7. Photoshop&#39;da tugma (uslubiy ko&#39;rsatma, 1.4-mashg&#39;ulot) <a class="header-anchor" href="#_7-photoshop-da-tugma-uslubiy-ko-rsatma-1-4-mashg-ulot" aria-label="Permalink to &quot;7. Photoshop&#39;da tugma (uslubiy ko&#39;rsatma, 1.4-mashg&#39;ulot)&quot;">​</a></h3><ol><li>File → New (<code>Ctrl + N</code>): <strong>1920×1080 px</strong>, 72 ppi, RGB, nomi «O&#39;yin menyusi».</li><li><strong>Rectangle Tool (U)</strong> bilan to&#39;rtburchak (masalan, 400×100 px).</li><li>Layers panelida shaklga ikki marta bosib, <strong>Color Picker</strong> bilan rang.</li><li><strong>Move Tool (V)</strong> bilan markazga.</li><li>Properties → <strong>Corners: 30 px</strong> — burchaklar yumaloq.</li><li>Properties → <strong>Stroke</strong>: rang va qalinlik (masalan, 4 px).</li><li><strong>Text Tool (T)</strong>: «START», Properties → Character: shrift, o&#39;lcham, rang; matn markazga.</li><li>Qo&#39;llanma bo&#39;yicha <strong>Layer Styles</strong>: gradient, Drop Shadow, Inner Glow, Outer Glow, Bevel &amp; Emboss.</li></ol><h3 id="_8-holatlarni-qatlamlarda-tayyorlash" tabindex="-1">8. Holatlarni qatlamlarda tayyorlash <a class="header-anchor" href="#_8-holatlarni-qatlamlarda-tayyorlash" aria-label="Permalink to &quot;8. Holatlarni qatlamlarda tayyorlash&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Layers:</span></span>
<span class="line"><span>  btn_start (Group)</span></span>
<span class="line"><span>    btn_start_normal   (shakl + matn + Drop Shadow)</span></span>
<span class="line"><span>    btn_start_hover    (nusxa: ochroq rang + Outer Glow)</span></span>
<span class="line"><span>    btn_start_pressed  (nusxa: to&#39;qroq rang, soya o&#39;chiq, 3 px pastga)</span></span></code></pre></div><ul><li>Normal guruhni <code>Ctrl + J</code> bilan nusxalang, nomini o&#39;zgartiring, faqat farqlarini tahrirlang.</li><li>Har holatni alohida eksport: boshqalarini yashirib (ko&#39;z belgisi), <strong>File → Export → Export As → PNG</strong> (Transparency). Fon qatlamini yashirish yoki o&#39;chirish shart.</li><li>Nomlash: <code>btn_start_normal.png</code>, <code>btn_start_hover.png</code>, <code>btn_start_pressed.png</code>.</li><li>Barcha holatlar <strong>bir xil o&#39;lchamdagi</strong> kanvasda — dvijokda almashtirilganda tugma «sakramaydi».</li><li>Bonus: 13-darsdagi atlas g&#39;oyasi — 3 holatni bitta sheetga (3 qator) yig&#39;ish mumkin.</li></ul><hr>`,23))]),i("div",k,[i("h2",b,[t(r,{name:"file-text"}),a[6]||(a[6]=l(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=o('<h3 id="_1-topshiriq-primary-yoki-secondary-oson" tabindex="-1">1-topshiriq. Primary yoki Secondary? (oson) <a class="header-anchor" href="#_1-topshiriq-primary-yoki-secondary-oson" aria-label="Permalink to &quot;1-topshiriq. Primary yoki Secondary? (oson)&quot;">​</a></h3><p>Quyidagi tugmalarni turlarga ajrating: Start, Back, OK, Cancel, Davom etish, Bekor qilish.</p><p><strong>Yechim:</strong> Primary: Start, OK, Davom etish. Secondary: Back, Cancel, Bekor qilish. Sabab: primary — asosiy maqsadli harakat (boshlash, tasdiqlash), secondary — chekinish yoki rad etish.</p><h3 id="_2-topshiriq-start-tugmasi-oson" tabindex="-1">2-topshiriq. START tugmasi (oson) <a class="header-anchor" href="#_2-topshiriq-start-tugmasi-oson" aria-label="Permalink to &quot;2-topshiriq. START tugmasi (oson)&quot;">​</a></h3><p>Uslubiy ko&#39;rsatma bo&#39;yicha 1920×1080 hujjatda yumaloq burchakli (30 px), stroke&#39;li «START» tugmasini chizing.</p><p><strong>Yechim:</strong> Ctrl + N (1920×1080, 72 ppi, RGB) → Rectangle Tool (U), ~400×100 → Color Picker (masalan, yashil) → Properties: Corners 30 px, Stroke 4 px to&#39;q yashil → Text Tool (T) «START», oq, qalin shrift, ~48 pt → Move Tool bilan markaz. Tekshirish: matn tugma ichida markazda, chetlari tekis.</p><h3 id="_3-topshiriq-uch-holat-o-rta" tabindex="-1">3-topshiriq. Uch holat (o&#39;rta) <a class="header-anchor" href="#_3-topshiriq-uch-holat-o-rta" aria-label="Permalink to &quot;3-topshiriq. Uch holat (o&#39;rta)&quot;">​</a></h3><p>2-topshiriqdagi tugmaning Normal, Hover va Pressed holatlarini alohida qatlamlarda yarating.</p><p><strong>Yechim:</strong></p><ol><li>Shakl va matnni <code>btn_start_normal</code> guruhiga (<code>Ctrl + G</code>), Drop Shadow (Distance 6 px).</li><li><code>Ctrl + J</code> → <code>btn_start_hover</code>: Color Overlay yoki Fill ochroq yashil, Outer Glow (Size 15 px).</li><li><code>Ctrl + J</code> → <code>btn_start_pressed</code>: to&#39;qroq yashil, Drop Shadow o&#39;chiq (yoki Inner Shadow), guruh 3 px pastga.</li><li>Tekshirish: ko&#39;z belgisini navbat bilan yoqib-o&#39;chirganda farq aniq ko&#39;rinadi, tugma chegarasi joyidan siljimaydi (pressed&#39;dagi 3 px dan tashqari).</li></ol><h3 id="_4-topshiriq-tugmalar-to-plami-va-eksport-qiyin" tabindex="-1">4-topshiriq. Tugmalar to&#39;plami va eksport (qiyin) <a class="header-anchor" href="#_4-topshiriq-tugmalar-to-plami-va-eksport-qiyin" aria-label="Permalink to &quot;4-topshiriq. Tugmalar to&#39;plami va eksport (qiyin)&quot;">​</a></h3><p>Primary («START») va Secondary («ORTGA») tugmalarni bir uslubda yarating, har biri uchun 3 holat, barchasini shaffof PNG qilib nomlab eksport qiling.</p><p><strong>Yechim:</strong></p><ul><li>Secondary: kulrang yoki kontur (Fill 0%, Stroke 4 px), kichikroq (320×80), matn «ORTGA».</li><li>Holatlar: Primary bilan bir xil mantiq (hover — ochroq/glow, pressed — to&#39;qroq/pastga).</li><li>Eksport: fonni yashirish → har holat uchun boshqalarini yashirib Export As → PNG. 6 ta fayl: <code>btn_start_normal.png</code>... <code>btn_ortga_pressed.png</code>.</li><li>Tekshirish: barcha PNG&#39;lar shaffof, bir holatdagi fayllar bir xil o&#39;lchamda.</li></ul><hr>',15))]),i("div",q,[i("h2",p,[t(r,{name:"file-text"}),a[9]||(a[9]=l(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=o("<ol><li>UI dizayn nima? <ul><li><em>Javob:</em> O&#39;yinchi o&#39;zaro ta&#39;sir qiladigan tugma, menyu, belgi kabi elementlarni o&#39;z ichiga olgan vizual va interaktiv qismni yaratish jarayoni.</li></ul></li><li>Primary va Secondary tugma farqi? <ul><li><em>Javob:</em> Primary — asosiy harakat (Start, OK), Secondary — bekor qilish, ortga (Cancel, Back).</li></ul></li><li>Tugmaning uchta holati? <ul><li><em>Javob:</em> Normal, Hover, Pressed.</li></ul></li><li>HUD nomi qayerdan kelib chiqqan? <ul><li><em>Javob:</em> Aviatsiyadan: muhim ma&#39;lumot uchuvchining old oynasiga tushirilgan.</li></ul></li><li>Photoshop&#39;da tugma holatlari qanday tayyorlanadi? <ul><li><em>Javob:</em> Alohida qatlamlarda (layerlarda), har biri alohida PNG qilib eksport qilinadi.</li></ul></li></ol><hr>",2))]),i("div",c,[i("h2",v,[t(r,{name:"file-text"}),a[12]||(a[12]=l(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=o("<ul><li><strong>Holatlar deyarli bir xil:</strong> o&#39;yinchi bosilganini sezmaydi — rang, soya va siljish farqini aniq qiling.</li><li><strong>Matn tugmadan chiqib ketadi:</strong> Font Size&#39;ni kamaytiring, matnni markazlang.</li><li><strong>Secondary tugma Primary&#39;dan yorqinroq:</strong> o&#39;yinchi adashadi — ierarxiyani saqlang.</li><li><strong>Oq fon bilan eksport:</strong> Background qatlamini yashiring, PNG Transparency.</li><li><strong>Holatlar har xil o&#39;lchamda:</strong> dvijokda tugma sakraydi — bir xil kanvas.</li><li><strong>Juda ko&#39;p effekt:</strong> Bevel + Glow + Gradient + Pattern birdaniga — tugma «og&#39;ir»; 2–3 effekt yetarli.</li></ul>",1))])])}const U=n(d,[["render",f]]);export{I as __pageData,U as default};
